const touchProjectMemoryItemProvenance = `-- name: TouchProjectMemoryItemProvenance :execrows
UPDATE project_memory_items
SET source_commit = ?, source_digest = ?, source_paths_json = ?,
    generation = ?, state = 'valid', state_reason = '', invalidated_at = NULL
WHERE id = ? AND generation <= ?
`

type TouchProjectMemoryItemProvenanceParams struct {
	SourceCommit    string
	SourceDigest    string
	SourcePathsJson string
	Generation      int64
	ID              string
	Generation_2    int64
}

// Re-confirm a fact whose content did not move: refresh only the provenance
// and the generation, leaving updated_at alone.
//
// Leaving updated_at alone is the whole point. "This fact has not changed
// since March" is information a pack's freshness ranking uses, and a re-index
// that bumped every timestamp would destroy it.
func (q *Queries) TouchProjectMemoryItemProvenance(ctx context.Context, arg TouchProjectMemoryItemProvenanceParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, touchProjectMemoryItemProvenance,
		arg.SourceCommit,
		arg.SourceDigest,
		arg.SourcePathsJson,
		arg.Generation,
		arg.ID,
		arg.Generation_2,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

