const updateProjectMemoryItem = `-- name: UpdateProjectMemoryItem :execrows
UPDATE project_memory_items
SET item_type = ?, scope = ?, item_key = ?,
    summary = ?, content = ?,
    source_paths_json = ?, source_commit = ?, source_digest = ?,
    generation = ?, state = ?, state_reason = ?, confidence = ?,
    metadata_json = ?, content_hash = ?, updated_at = ?, invalidated_at = ?,
    authority = ?, authority_reason = ?, repo_identity = ?, provenance_kind = ?,
    promotion_authority = ?, verified_commit = ?, integrated_commit = ?,
    evidence_class = ?
WHERE id = ? AND generation <= ?
`

type UpdateProjectMemoryItemParams struct {
	ItemType           string
	Scope              string
	ItemKey            string
	Summary            string
	Content            string
	SourcePathsJson    string
	SourceCommit       string
	SourceDigest       string
	Generation         int64
	State              string
	StateReason        string
	Confidence         float64
	MetadataJson       string
	ContentHash        string
	UpdatedAt          time.Time
	InvalidatedAt      sql.NullTime
	Authority          string
	AuthorityReason    string
	RepoIdentity       string
	ProvenanceKind     string
	PromotionAuthority string
	VerifiedCommit     string
	IntegratedCommit   string
	EvidenceClass      string
	ID                 string
	Generation_2       int64
}

// Generation-conditioned update: apply only if the stored row is not already
// at a NEWER generation than the writer's.
//
// `<=` rather than `=` is deliberate. A pass legitimately writes the same fact
// more than once within its own generation (a file summary refined after its
// module is known), and an equal generation is the same pass, not a stale one.
// What must never apply is a write whose generation is behind the row's --
// that is a pass the repository has moved past.
func (q *Queries) UpdateProjectMemoryItem(ctx context.Context, arg UpdateProjectMemoryItemParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateProjectMemoryItem,
		arg.ItemType,
		arg.Scope,
		arg.ItemKey,
		arg.Summary,
		arg.Content,
		arg.SourcePathsJson,
		arg.SourceCommit,
		arg.SourceDigest,
		arg.Generation,
		arg.State,
		arg.StateReason,
		arg.Confidence,
		arg.MetadataJson,
		arg.ContentHash,
		arg.UpdatedAt,
		arg.InvalidatedAt,
		arg.Authority,
		arg.AuthorityReason,
		arg.RepoIdentity,
		arg.ProvenanceKind,
		arg.PromotionAuthority,
		arg.VerifiedCommit,
		arg.IntegratedCommit,
		arg.EvidenceClass,
		arg.ID,
		arg.Generation_2,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

