const upsertProjectMemoryContextManifest = `-- name: UpsertProjectMemoryContextManifest :exec

INSERT INTO project_memory_context_manifests (
    id, project_id, repo_id, workflow_run_id, task_ref, role,
    pack_digest, policy_version, generation, indexed_commit,
    item_ids_json, item_count, selected_bytes, estimated_tokens,
    created_at, updated_at, item_versions_json, role_head_sha
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(id) DO UPDATE SET
    repo_id = excluded.repo_id,
    pack_digest = excluded.pack_digest,
    policy_version = excluded.policy_version,
    generation = excluded.generation,
    indexed_commit = excluded.indexed_commit,
    item_ids_json = excluded.item_ids_json,
    item_count = excluded.item_count,
    selected_bytes = excluded.selected_bytes,
    estimated_tokens = excluded.estimated_tokens,
    item_versions_json = excluded.item_versions_json,
    role_head_sha = excluded.role_head_sha,
    updated_at = excluded.updated_at
`

type UpsertProjectMemoryContextManifestParams struct {
	ID               string
	ProjectID        string
	RepoID           string
	WorkflowRunID    string
	TaskRef          string
	Role             string
	PackDigest       string
	PolicyVersion    int64
	Generation       int64
	IndexedCommit    string
	ItemIdsJson      string
	ItemCount        int64
	SelectedBytes    int64
	EstimatedTokens  int64
	CreatedAt        time.Time
	UpdatedAt        time.Time
	ItemVersionsJson string
	RoleHeadSha      string
}

// Context manifests (migration 0145). A manifest records the IDENTITIES of the
// facts one execution received, never their content and never the prompt they
// were rendered into.
// Idempotent by derived id: re-provisioning the same context after a restart
// addresses the same row rather than appending a second observation of the
// same answer. created_at is preserved so "when was this execution first told
// this" survives a re-record.
func (q *Queries) UpsertProjectMemoryContextManifest(ctx context.Context, arg UpsertProjectMemoryContextManifestParams) error {
	_, err := q.db.ExecContext(ctx, upsertProjectMemoryContextManifest,
		arg.ID,
		arg.ProjectID,
		arg.RepoID,
		arg.WorkflowRunID,
		arg.TaskRef,
		arg.Role,
		arg.PackDigest,
		arg.PolicyVersion,
		arg.Generation,
		arg.IndexedCommit,
		arg.ItemIdsJson,
		arg.ItemCount,
		arg.SelectedBytes,
		arg.EstimatedTokens,
		arg.CreatedAt,
		arg.UpdatedAt,
		arg.ItemVersionsJson,
		arg.RoleHeadSha,
	)
	return err
}

const upsertProjectMemoryFile = `-- name: UpsertProjectMemoryFile :exec
INSERT OR REPLACE INTO project_memory_files (
    project_id, repo_id, path, content_digest, size_bytes, generation,
    indexed_commit, updated_at
) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
`

type UpsertProjectMemoryFileParams struct {
	ProjectID     string
	RepoID        string
	Path          string
	ContentDigest string
	SizeBytes     int64
	Generation    int64
	IndexedCommit string
	UpdatedAt     time.Time
}

// The per-file digest ledger. OR REPLACE is correct here and nowhere else in
// this file: a file row is not a derived fact with provenance to protect, it
// is the observation "at generation N this path hashed to D", and the newest
// observation is the only one worth keeping.
func (q *Queries) UpsertProjectMemoryFile(ctx context.Context, arg UpsertProjectMemoryFileParams) error {
	_, err := q.db.ExecContext(ctx, upsertProjectMemoryFile,
		arg.ProjectID,
		arg.RepoID,
		arg.Path,
		arg.ContentDigest,
		arg.SizeBytes,
		arg.Generation,
		arg.IndexedCommit,
		arg.UpdatedAt,
	)
	return err
}
